namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use App\Models\VirtualServer;
use Illuminate\Http\Request;
use Illuminate\Http\JsonResponse;

class ServerOperationsController extends Controller
{
    public function reboot(Request $request): JsonResponse
    {
        if (!$request->user()->tokenCan('servers:reboot')) {
            return response()->json(['error' => 'Missing token ability'], 403);
        }

        $server = $request->user()->currentTeam
            ->virtualServers()
            ->findOrFail($request->input('server_id'));

        $this->authorize('reboot', $server);
        $server->reboot();

        return response()->json(['status' => 'Reboot dispatched', 'server_id' => $server->id]);
    }
}
